def has_single_arg(func):
    """Return True if func has exactly one argument and no keyword-only arguments.
    """
    if PY2:
        spec = inspect.getargspec(func)
        return len(spec.args) == 1 and not spec.varargs and not spec.keywords
    else:
        spec = inspect.signature(func)
        return len(spec.parameters) == 1 and all(p.kind not in (p.VAR_POSITIONAL, p.VAR_KEYWORD, p.KEYWORD_ONLY) for p in spec.parameters.values())

